using WW.Math;

namespace Examples {
    public class LineExample {
        public void Test() {
            DxfModel model = new DxfModel(DxfVersion.Dxf14);

            DxfLineType lineType = new DxfLineType("DashDot", "Dashed & dotted", new double[] { 0.5, -0.2, 0, -0.2 });
            model.LineTypes.Add(lineType);

