            An example of how to create a dxf file with an aligned dimension.
            
using System;
using System.Drawing;

using WW.Cad.Base;
using WW.Cad.IO;
using WW.Cad.Model;
using WW.Cad.Model.Entities;
using WW.Cad.Model.Tables;

using WW.Math;

namespace Examples {
	public class AlignedDimensionExample {
		public void Test()
		{
			DxfModel model = new DxfModel(DxfVersion.Dxf14);
			
			DxfLayer layer = new DxfLayer("DIMENSIONS");
			model.Layers.Add(layer);

			DxfBlock block = new DxfBlock("ALIGNED_DIMENSIONS");
			model.Blocks.Add(block);
			
			DxfInsert insert = new DxfInsert(block, new Point3D(0, -20, 0));
			insert.Layer = layer;
			model.Entities.Add(insert);
			
			// DxfDimension with no text.
			DxfDimension.Aligned alignedDimension1 = new DxfDimension.Aligned(model.DefaultDimensionStyle);
			alignedDimension1.DimensionStyleOverrides.TickSize = 0.5;
			alignedDimension1.DimensionStyleOverrides.DimensionLineExtension = 0.3;
			alignedDimension1.DimensionStyleOverrides.DimensionLineColor = Color.Red;
			alignedDimension1.DimensionStyleOverrides.ExtensionLineColor = Color.Green;
			// This means no text.
			alignedDimension1.Text = " ";
			alignedDimension1.Layer = layer;
			alignedDimension1.DimensionLineLocation = new Point3D(2d, 2d, 0d);
			alignedDimension1.ExtensionLine1StartPoint = new Point3D(3d, 1, 0d);
			alignedDimension1.ExtensionLine2StartPoint = new Point3D(0d, 0d, 0d);
			block.Entities.Add(alignedDimension1);

			// DxfDimension with text that doesn't fit between extension lines.
			DxfDimension.Aligned alignedDimension2 = new DxfDimension.Aligned(model.DefaultDimensionStyle);
			alignedDimension2.DimensionStyleOverrides.ArrowSize = 1d;
			alignedDimension2.Text = "This is a long dimension text";
			alignedDimension2.Layer = layer;
			alignedDimension2.DimensionLineLocation = new Point3D(2d, 4d, 0d);
			alignedDimension2.ExtensionLine1StartPoint = new Point3D(3d, 3d, 0d);
			alignedDimension2.ExtensionLine2StartPoint = new Point3D(0d, 2d, 0d);
			block.Entities.Add(alignedDimension2);

			// DxfDimension with big arrows.
			DxfDimension.Aligned alignedDimension3 = new DxfDimension.Aligned(model.DefaultDimensionStyle);
			alignedDimension3.DimensionStyleOverrides.ArrowSize = 2d;
			alignedDimension3.DimensionStyleOverrides.TextAboveDimensionLine = true;
			alignedDimension3.Layer = layer;
			alignedDimension3.DimensionLineLocation = new Point3D(2d, 6d, 0d);
			alignedDimension3.ExtensionLine1StartPoint = new Point3D(3d, 5d, 0d);
			alignedDimension3.ExtensionLine2StartPoint = new Point3D(0d, 4d, 0d);
			block.Entities.Add(alignedDimension3);

			// DxfDimension with text aligned with dimension line.
			DxfDimension.Aligned alignedDimension4 = new DxfDimension.Aligned(model.DefaultDimensionStyle);
			alignedDimension4.DimensionStyleOverrides.ArrowSize = 1d;
			alignedDimension4.DimensionStyleOverrides.TextInsideHorizontal = false;
			alignedDimension4.DimensionStyleOverrides.TextAboveDimensionLine = true;
			alignedDimension4.Layer = layer;
			alignedDimension4.DimensionLineLocation = new Point3D(2d, 8d, 0d);
			alignedDimension4.ExtensionLine1StartPoint = new Point3D(3d, 7d, 0d);
			alignedDimension4.ExtensionLine2StartPoint = new Point3D(0d, 6d, 0d);
			block.Entities.Add(alignedDimension4);

			DxfWriter.Write("Test.dxf", model, false);
		}
	}
}

