			DxfLayer layer = new DxfLayer("DIMENSIONS");
			model.Layers.Add(layer);

			DxfBlock block = new DxfBlock("ALIGNED_DIMENSIONS");
			model.Blocks.Add(block);
			
			DxfInsert insert = new DxfInsert(block, new Point3D(0, -20, 0));
			insert.Layer = layer;
			model.Entities.Add(insert);
			
			// DxfDimension with no text.
			DxfDimension.Aligned alignedDimension1 = new DxfDimension.Aligned(model.DefaultDimensionStyle);
			alignedDimension1.DimensionStyleOverrides.TickSize = 0.5;
			alignedDimension1.DimensionStyleOverrides.DimensionLineExtension = 0.3;
			alignedDimension1.DimensionStyleOverrides.DimensionLineColor = Color.Red;
