            An example of how to create a dxf file with a 3-point angular dimension.
            
using System;
using System.Drawing;

using WW.Cad.Base;
using WW.Cad.IO;
using WW.Cad.Model;
using WW.Cad.Model.Entities;
using WW.Cad.Model.Tables;

using WW.Math;

namespace Examples {
	public class Angular3PointDimensionExample {
		public void Test()
		{
			DxfModel model = new DxfModel(DxfVersion.Dxf14);
			
			DxfLayer layer = new DxfLayer("DIMENSIONS");
			model.Layers.Add(layer);

			DxfBlock block = new DxfBlock("ANGULAR3POINT_DIMENSIONS");
			model.Blocks.Add(block);
			
			DxfInsert insert = new DxfInsert(block, new Point3D(20, -15, 0));
			insert.Layer = layer;
			model.Entities.Add(insert);

			DxfDimension.Angular3Point dimension1 = new DxfDimension.Angular3Point(model.DefaultDimensionStyle);
			dimension1.AngleVertex = new Point3D(0, 0, 0);
			dimension1.DimensionLineArcPoint = new Point3D(0d, -1d, 0d);
			dimension1.ExtensionLine1StartPoint = new Point3D(-0.3d, 0.4d, 0d);
			dimension1.ExtensionLine2StartPoint = new Point3D(0.4d, 0.4d, 0d);
			block.Entities.Add(dimension1);

			// Same dimension but swapped start and end point basically.
			// DxfDimension with some overridden dimension style settings.
			DxfDimension.Angular3Point dimension2 = new DxfDimension.Angular3Point(model.DefaultDimensionStyle);
			dimension2.AngleVertex = new Point3D(0, 2, 0);
			dimension2.DimensionLineArcPoint = new Point3D(0d, 3d, 0d);
			dimension2.ExtensionLine1StartPoint = new Point3D(0.4d, 2.4d, 0d);
			dimension2.ExtensionLine2StartPoint = new Point3D(-0.3d, 2.4d, 0d);
			dimension2.DimensionStyleOverrides.AngularUnit = AngularUnit.Gradians;
			dimension2.DimensionStyleOverrides.TextAboveDimensionLine = true; // ignored for angular dimensions
			block.Entities.Add(dimension2);

			DxfWriter.Write("Test.dxf", model, false);
		}
	}
}

