        {
            DxfModel model = new DxfModel(DxfVersion.Dxf14);
    
            // Create a polygon spline surface.
            DxfPolygonSplineMesh polyline6 = new DxfPolygonSplineMesh(SplineType.CubicBSpline);
            polyline6.Color = Color.Green;
            polyline6.SetControlPointsDimensionLengths(4, 4);
            polyline6.ControlPoints[0, 0] = new DxfVertex3D(0, 4, 0);
            polyline6.ControlPoints[0, 1] = new DxfVertex3D(0, 5, 0);
            polyline6.ControlPoints[0, 2] = new DxfVertex3D(0, 6, 0);
            polyline6.ControlPoints[0, 3] = new DxfVertex3D(0, 7, 0);
            polyline6.ControlPoints[1, 0] = new DxfVertex3D(1, 4, 0);
            polyline6.ControlPoints[1, 1] = new DxfVertex3D(1, 5, 1);
            polyline6.ControlPoints[1, 2] = new DxfVertex3D(1, 6, 1);
            polyline6.ControlPoints[1, 3] = new DxfVertex3D(1, 7, 0);
            polyline6.ControlPoints[2, 0] = new DxfVertex3D(2, 4, 0);
            polyline6.ControlPoints[2, 1] = new DxfVertex3D(2, 5, 1);
            polyline6.ControlPoints[2, 2] = new DxfVertex3D(2, 6, 1);
            polyline6.ControlPoints[2, 3] = new DxfVertex3D(2, 7, 0);
            polyline6.ControlPoints[3, 0] = new DxfVertex3D(3, 4, 0);
            polyline6.ControlPoints[3, 1] = new DxfVertex3D(3, 5, 0);
            polyline6.ControlPoints[3, 2] = new DxfVertex3D(3, 6, 0);
            polyline6.ControlPoints[3, 3] = new DxfVertex3D(3, 7, 0);
            model.Entities.Add(polyline6);
    
